#!/usr/bin/env python3
"""Regenerate report/claims.csv from an explicit, quoted table.

The claims ledger is the review surface for the report: one row per
quantitative or qualitative claim that appears in report/final_report.tex,
with its measured n, its interval, its status, the exact file the number came
from, and the qualifier that must travel with the claim.

The rows are written here rather than edited in place because the free-text
fields contain commas, and a hand-edited CSV of this shape is silently
corruptible. ``tools/check_tex.py`` verifies the correspondence between this
file and the report.

Usage:
    python tools/build_claims_csv.py
"""

from __future__ import annotations

import csv
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parents[1]
